"""Evaluate answers generated by an OpenAI-compatible served Hugging Face model."""

import argparse
import asyncio
import json
from pathlib import Path

import yaml

from pipelines.evaluate_llm_jp import EvaluationError, evaluate


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("-p", "--settings", default="./yamls/evaluate_llm_jp_settings_format.yaml")
    parser.add_argument("-q", "--eval-qa", help="Evaluation JSON/JSONL file or directory (overrides YAML)")
    parser.add_argument("-o", "--output", help="Output directory (overrides YAML output_path)")
    parser.add_argument("--stage", choices=("generate", "judge", "both"), default="both",
                        help="Generate answers, judge saved answers, or run both (default: both)")
    args = parser.parse_args()
    try:
        with Path(args.settings).expanduser().open(encoding="utf-8") as stream:
            settings = yaml.safe_load(stream)
        if not isinstance(settings, dict):
            raise EvaluationError("Settings must be a YAML mapping")
        if args.output:
            settings["output_path"] = args.output
        dataset = args.eval_qa or settings.get("eval_qa_path")
        if not dataset:
            raise EvaluationError("eval_qa_path or --eval-qa is required")
        stats = asyncio.run(evaluate(settings, Path(dataset).expanduser().resolve(), stage=args.stage))
        print(json.dumps(stats, ensure_ascii=False, indent=2))
        remaining = stats["remaining_generation_records"] if args.stage == "generate" else stats["remaining_records"]
        return 1 if remaining else 0
    except (EvaluationError, OSError, ValueError, KeyError, yaml.YAMLError) as exc:
        parser.exit(1, f"Evaluation failed: {exc}\n")


if __name__ == "__main__":
    raise SystemExit(main())
